import express from 'express';
import rateLimit from 'express-rate-limit';
import {
  ComputeTaskApiError,
  ComputeTaskApiService,
} from '../services/forecast/compute-task-api-service.js';
import { ComputeNodeSession } from '../services/forecast/compute-task-api-types.js';
// error-response.js is CJS. Import the .cjs shim (generated by copy-build-assets.mjs)
// so that Node 20 can load it via ESM default import. The .cjs file exists only
// post-build in dist/; suppress the pre-build type-resolution error.
import _errRespModule from '../utils/error-response.js';
const createErrorResponse = (_errRespModule as any).createErrorResponse as (
  message: string,
  code?: string,
  extras?: Record<string, unknown>,
) => object;

interface AuthenticatedRequest extends express.Request {
  computeNodeSession?: ComputeNodeSession;
}

export function createComputeTaskRouter(
  service: ComputeTaskApiService = new ComputeTaskApiService()
): express.Router {
  const router = express.Router();

  const registerLimiter = rateLimit({
    windowMs: 60 * 1000,
    max: 30,
    standardHeaders: true,
    legacyHeaders: false,
  });

  router.post('/compute/nodes/register', registerLimiter, (req, res) => {
    try {
      const walletAddress = String(req.body?.walletAddress || '').trim();
      const capabilities =
        req.body?.capabilities && typeof req.body.capabilities === 'object'
          ? req.body.capabilities
          : {};
      const session = service.registerNode(walletAddress, capabilities);
      return res.status(201).json({
        success: true,
        nodeId: session.nodeId,
        token: session.token,
        walletAddress: session.walletAddress,
        capabilities: session.capabilities,
      });
    } catch (error) {
      return sendRouteError(res, error);
    }
  });

  router.use((req: AuthenticatedRequest, res, next) => {
    try {
      const authHeader = String(req.headers.authorization || '');
      if (!authHeader.startsWith('Bearer ')) {
        throw new ComputeTaskApiError('Missing bearer token', 401);
      }
      const token = authHeader.slice('Bearer '.length).trim();
      req.computeNodeSession = service.authenticateToken(token);
      return next();
    } catch (error) {
      return sendRouteError(res, error);
    }
  });

  router.get('/compute/tasks/available', (req: AuthenticatedRequest, res) => {
    try {
      const session = req.computeNodeSession!;
      const tasks = service.listAvailableTasks(session);
      return res.json({
        success: true,
        tasks,
      });
    } catch (error) {
      return sendRouteError(res, error);
    }
  });

  router.post('/compute/tasks/:id/claim', (req: AuthenticatedRequest, res) => {
    try {
      const session = req.computeNodeSession!;
      const task = service.claimTask(session, req.params.id);
      const heartbeatDeadline =
        task.nextHeartbeatDueAt ||
        new Date(
          Date.now() + service.getHeartbeatTimeoutMs()
        ).toISOString();
      return res.json({
        success: true,
        leaseId: task.leaseId,
        heartbeatDeadline,
        status: task.status,
      });
    } catch (error) {
      return sendRouteError(res, error);
    }
  });

  router.post('/compute/tasks/:id/heartbeat', (req: AuthenticatedRequest, res) => {
    try {
      const session = req.computeNodeSession!;
      const leaseId = String(req.body?.leaseId || '').trim();
      const rawProgress = Number(req.body?.progress ?? 0);
      const progress = Number.isFinite(rawProgress) ? Math.min(100, Math.max(0, rawProgress)) : 0;
      const statusMessage =
        typeof req.body?.statusMessage === 'string' ? req.body.statusMessage : undefined;
      const task = service.heartbeatTask(
        session,
        req.params.id,
        leaseId,
        progress,
        statusMessage
      );
      return res.json({
        success: true,
        ok: true,
        taskId: task.id,
        nextHeartbeatBy:
          task.nextHeartbeatDueAt ||
          new Date(Date.now() + service.getHeartbeatTimeoutMs()).toISOString(),
      });
    } catch (error) {
      return sendRouteError(res, error);
    }
  });

  router.post('/compute/tasks/:id/complete', async (req: AuthenticatedRequest, res) => {
    try {
      const session = req.computeNodeSession!;
      const leaseId = String(req.body?.leaseId || '').trim();
      const outputCid = String(req.body?.outputCid || '').trim();
      const verificationReportCid =
        typeof req.body?.verificationReportCid === 'string'
          ? req.body.verificationReportCid
          : undefined;
      const metrics =
        req.body?.metrics && typeof req.body.metrics === 'object'
          ? req.body.metrics
          : undefined;

      const result = await service.completeTask(
        session,
        req.params.id,
        leaseId,
        outputCid,
        verificationReportCid,
        metrics
      );

      return res.json({
        success: true,
        ...result,
      });
    } catch (error) {
      return sendRouteError(res, error);
    }
  });

  // Periodically requeue stalled tasks even when no requests arrive
  const sweepInterval = setInterval(() => {
    try {
      service.requeueStalledTasks();
    } catch {
      // Sweep errors are non-fatal
    }
  }, 60_000);
  sweepInterval.unref();

  return router;
}

function sendRouteError(
  res: express.Response,
  error: unknown
): express.Response {
  if (error instanceof ComputeTaskApiError) {
    const code = computeTaskErrorCode(error.statusCode);
    return res
      .status(error.statusCode)
      .json(createErrorResponse(error.message, code));
  }
  return res
    .status(500)
    .json(createErrorResponse('Internal server error', 'INTERNAL_SERVER_ERROR'));
}

function computeTaskErrorCode(statusCode: number): string {
  switch (statusCode) {
    case 400:
      return 'VALIDATION_ERROR';
    case 401:
      return 'UNAUTHORIZED';
    case 403:
      return 'FORBIDDEN';
    case 404:
      return 'NOT_FOUND';
    case 409:
      return 'CONFLICT';
    case 429:
      return 'RATE_LIMIT_EXCEEDED';
    default:
      return 'COMPUTE_TASK_ERROR';
  }
}
